// Hazard Detection Unit (ID stage)
struct PReg { int Rd; bool MemRead; int Rs, Rt; };
PReg ID_EX, IF_ID; // Pipeline Register Contents

// Load-Use Hazard check (RAW)
bool StallCondition = (ID_EX.MemRead) && (
    (ID_EX.Rd == IF_ID.Rs) ||
    (ID_EX.Rd == IF_ID.Rt)
);

if (StallCondition) {
    PC_Write_Enable = 0; // Stop IF progression
    IF_ID_Write_Enable = 0;
    ID_EX.Control = NOP_CNTRL; // Insert Bubble (stall cycle)
}

// Forwarding Unit Logic (EX stage input bypass)
PReg EX_MEM, MEM_WB;

// Forward M -> E (EX/MEM result used in current EX)
if (EX_MEM.RegWrite && EX_MEM.Rd == ID_EX.Rs)
    ALU_InputA = EX_MEM.ALU_Result;

// Forward W -> E (MEM/WB result used in current EX)
else if (MEM_WB.RegWrite && MEM_WB.Rd == ID_EX.Rs)
    ALU_InputA = MEM_WB.WriteData;
